solution.solution.py:
def NOT(a):
    return 1 - a

def AND(a, b):
    return 1 if a == 1 and b == 1 else 0

def OR(a, b):
    return 1 if a == 1 or b == 1 else 0

def XOR(a, b):
    return 1 if a != b else 0

def NAND(a, b):
    return 0 if a == 1 and b == 1 else 1

def XOR_FROM_NAND(a, b):
    n = NAND(a, b)
    return NAND(NAND(a, n), NAND(b, n))

unitTests:
PAIRS = [(0, 0), (0, 1), (1, 0), (1, 1)]

@test("NOT")
def _():
    check_eq(NOT(0), 1)
    check_eq(NOT(1), 0)

@test("the truth tables")
def _():
    check_eq([AND(a, b) for a, b in PAIRS], [0, 0, 0, 1])
    check_eq([OR(a, b) for a, b in PAIRS], [0, 1, 1, 1])
    check_eq([XOR(a, b) for a, b in PAIRS], [0, 1, 1, 0])
    check_eq([NAND(a, b) for a, b in PAIRS], [1, 1, 1, 0])

@test("XOR from four NANDs")
def _():
    check_eq([XOR_FROM_NAND(a, b) for a, b in PAIRS], [0, 1, 1, 0])

